            },
            {
              "id": "risk_notes",
              "label": "Risk Notes",
              "type": "string",
              "direction": "output",
              "variable": "vars.risk_notes"
            }
          ],
          "outcomes": [
            { "id": "approve", "name": "Approve", "type": "string", "isPrimary": true, "action": "Continue" },
